import{_ as e}from"./chunks/exchange.WBTyBzew.js";import{_ as r,o as t,c as l,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Кошелёк, почта и рынок","description":"","frontmatter":{"pageId":"players/economy","contentRevision":6},"headers":[],"relativePath":"ru/players/economy.md","filePath":"ru/players/economy.md"}'),o={name:"ru/players/economy.md"};function s(n,a,p,c,h,d){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="кошелек-почта-и-рынок" tabindex="-1">Кошелёк, почта и рынок <a class="header-anchor" href="#кошелек-почта-и-рынок" aria-label="Permalink to &quot;Кошелёк, почта и рынок&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><img class="wiki-art" src="'+e+'" alt="Обмен проходит через серверный escrow; доставка — через почту." width="960" height="440"><p class="wiki-caption">Обмен проходит через серверный escrow; доставка — через почту.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><ol class="flow-diagram" aria-label="Схема процесса"><li><strong>Намерение</strong><span>Предметы/пешки/кошелёк и исходный request id.</span></li><li><strong>Снимок</strong><span>Журнал и принятие точной домашней карты.</span></li><li><strong>Escrow</strong><span>Сервер хранит до расчёта или отмены.</span></li><li><strong>Почта</strong><span>Получение → сохранение → подтверждение.</span></li></ol><p>Для штатных операций нужны консоль связи и запитанные торговые маяки; предметы выбираются из обслуживаемой зоны. Кошелёк — серверный баланс серебра, а не стопка на карте. Внесение серебра переносит его в баланс; вывод доставляется через серверную посылку.</p><p>Выставь предметы или пешку обычным лотом, задай цену и проверь состав. Покупатель платит кошельком, товар уходит в доставку, продавец получает выручку с учётом комиссии. Непроданные лоты по умолчанию истекают через 30 дней.</p><p>Проверяй почту после сделки и обрыва соединения. Сервер удерживает отправленное в эскроу до завершения, а возвраты оформляет посылками.</p><h2 id="wallet-market" tabindex="-1">Как внести серебро, купить и получить товар? <a class="header-anchor" href="#wallet-market" aria-label="Permalink to &quot;Как внести серебро, купить и получить товар? {#wallet-market}&quot;">​</a></h2><p>Выбери колониста → правый клик по <strong>консоли связи</strong> → <strong>Rimlink</strong>. Предметы выбираются из зоны работающих орбитальных торговых маяков. Кошелёк — число на сервере; стопки серебра на полу сами в него не попадают.</p><ol><li>Положи серебро под маяк. В «Кошельке» выбери внесение и дождись сохранения/отправки операции.</li><li>Открой рынок, проверь содержимое лота, цену и владельца. Покупка оплачивается только кошельком.</li><li>После успешной покупки проверь новый баланс и «Почту». Вернись на домашнюю карту: товары приходят капсулой; «Принять сейчас» запрашивает доставку немедленно.</li><li>Для удобного места приземления поставь <strong>Architect → Misc → Rimlink delivery spot</strong>. Без него используется первый маяк либо обычное место торговых капсул.</li><li>Чтобы снова получить физическое серебро, выбери вывод из кошелька и получи посылку дома.</li></ol><p>Если лот успел купить другой игрок, не отправляй продавцу деньги отдельно: обнови список и выбери другой лот. Серверный кошелёк не даёт право использовать деньги другого члена альянса.</p><h2 id="selling-fees" tabindex="-1">Как продать и почему баланс может стать отрицательным? <a class="header-anchor" href="#selling-fees" aria-label="Permalink to &quot;Как продать и почему баланс может стать отрицательным? {#selling-fees}&quot;">​</a></h2><p>В «Моих лотах» выбери предметы или одну пешку, укажи цену и подтверди отправку. Они уходят с карты в escrow до продажи. «Забрать» возвращает лот почтой; по умолчанию непроданное возвращается через 30 дней. Перед продажей колониста учти: это реальный уход с навыками, здоровьем и снаряжением, не копия.</p><p>Плата за хранение по умолчанию — 0,5% стоимости за реальные сутки после трёх бесплатных дней <strong>для пешек и портящихся вещей</strong>, не для каждого стального слитка. Взимается при выходе из хранения. Для лота она идёт из выручки, затем кошелька, и может создать долг. Для получаемой посылки не забирается больше доступного кошелька. Уточняй настройки сервера.</p><p>При долге закрываются покупки, новые лоты и отправка; внесение серебра или продажи могут погасить долг. При угрозе закрывается новый отток, но получение, покупки, возврат лота и почта продолжают работать. Серверный кошелёк, лоты и ожидающие товары учитываются в богатстве: это не способ спрятать активы от защиты/рейдов.</p><p>Заявленная другим игроком стоимость подарка, обмена или рейдовой посылки учитывается по прежним правилам доверия. Наличие защищённой UUID/custody-связи сохраняет эти правила, включая ожидающий решения подарок. Серверная оценка продукции аванпоста и реальное денежное эскроу учитываются отдельно. Смешанный собственный возврат с пешкой и предметами включает полную стоимость предметов с количеством в стопках. Физический импорт засчитывается один раз по полному связанному содержимому, включая старые посылки с частичной сохранённой оценкой. Серебро, зачисляемое в кошелёк, учитывается отдельно от физических вещей.</p><h2 id="exchange-recovery" tabindex="-1">Что делать, если ответ на отправку потерян? <a class="header-anchor" href="#exchange-recovery" aria-label="Permalink to &quot;Что делать, если ответ на отправку потерян? {#exchange-recovery}&quot;">​</a></h2><p>Вещи удаляются с карты с журналом, создаётся точный снимок и только после его принятия продолжается серверная операция. Потеря ответа не означает отказ: повторяется <strong>исходный запрос</strong>, а не новая продажа тех же вещей. Переподключись и проверь лот/почту/баланс. Окончательный отказ возвращает содержимое один раз и сохраняет журнал до сохранения возврата.</p><p>Не удаляй outbox и не загружай сейв до отправки. Если автоматическое восстановление требует ручной помощи, сохрани файлы, время и id операции. Отсутствующая в почте посылка и уже распакованная, но не подтверждённая снимком доставка — разные состояния.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>По умолчанию хранение после 3 бесплатных дней стоит 0,5% в сутки. Долг, угроза на карте, заморозка или запрещённые defName ограничивают операции. Комиссии и лимиты задаёт сервер.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./gifts-trades">Подарки и двусторонние сделки</a></li><li><a href="./auctions">Аукционы</a></li><li><a href="./procurement">Заказы, контракты и общие цели</a></li></ul>',25)])])}const f=r(o,[["render",s]]);export{u as __pageData,f as default};
